  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_map = {n['id']: n for n in nodes}
    children_map = {}
    for n in nodes:
        parent = n.get('parent')
        if parent is not None:
            children_map.setdefault(parent, []).append(n['id'])
    root_id = None
    for n in nodes:
        if n['parent'] is None:
            root_id = n['id']
            break
    if root_id is None:
        raise ValueError("No root node found")
    subtree_cache = {}
    def compute_subtree(node_id):
        if node_id not in subtree_cache:
            ids = {node_id}
            for child_id in children_map.get(node_id, []):
                ids.update(compute_subtree(child_id))
            subtree_cache[node_id] = ids
        return subtree_cache[node_id]
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    retained_set = set(node_map.keys())
    removed_order = []
    for n in sorted_nodes:
        nid = n['id']
        if nid not in retained_set:
            continue
        if nid == root_id:
            continue
        if not n['removable']:
            continue
        if n['symbol'] in required_symbols:
            continue
        subtree = compute_subtree(nid)
        remaining_after = retained_set - subtree
        ok = True
        for sym in required_symbols:
            found = False
            for rid in remaining_after:
                if node_map[rid]['symbol'] == sym:
                    found = True
                    break
            if not found:
                ok = False
                break
        if ok:
            retained_set -= subtree
            removed_order.append(nid)
    retained_ids = sorted(retained_set)
    return {'removed_node_ids': removed_order, 'retained_node_ids': retained_ids}
